9	const EURO_FORMATTER = new Intl.NumberFormat("en-IE", {
10	  style: "currency",
11	  currency: "EUR",
12	  maximumFractionDigits: 0,
13	});
14	
15	const COMPACT_FORMATTER = new Intl.NumberFormat("en-US", {
16	  notation: "compact",
17	  maximumFractionDigits: 1,
18	});
19	
20	/** "€1,200" — whole-euro currency, used for prices, budgets, payouts. */
21	export function formatEuros(amount: number): string {
22	  return EURO_FORMATTER.format(amount);
23	}
24	
25	/** "12.4K", "1.2M" — compact counts for followers, impressions, etc. */
26	export function formatCompact(value: number): string {
27	  return COMPACT_FORMATTER.format(value);
28	}
29	
30	/** "4.2%" — a fraction (0.042) rendered as a percentage string. */
31	export function formatPercentFromFraction(fraction: number, digits = 1): string {
32	  return `${(fraction * 100).toFixed(digits)}%`;
33	}
34	
35	/** "92%" — an already-scaled 0..100 score rendered as a percent. */
36	export function formatScore(score: number): string {
37	  return `${Math.round(score)}%`;
38	}
39	
40	/** "Aug 12, 2026" */
41	export function formatDate(date: Date | string): string {
42	  const d = typeof date === "string" ? new Date(date) : date;
43	  return d.toLocaleDateString("en-US", {
44	    year: "numeric",
45	    month: "short",
46	    day: "numeric",
47	  });
48	}
49	
50	/** Deterministic initials for avatar fallbacks. */
51	export function initials(name: string): string {
52	  return name
53	    .split(" ")
54	    .filter(Boolean)
55	    .slice(0, 2)
56	    .map((part) => part[0]?.toUpperCase() ?? "")
57	    .join("");
58	}
